            repetitionOrTimeBn = "কখন ও কীভাবে পড়বেন এই দোয়া?",
            titleBn = "কখন পড়বেন ইসমে আজমের দোয়া? (হাদীসের স্পষ্ট প্রমাণ ও আমলের নিয়ম)",
            arabicText = "اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدَ، لاَ إِلَهَ إِلاَّ أَنْتَ وَحْدَكَ لاَ شَرِيكَ لك الْمَنَّانُ بَدِيعَ السَّمَوَاتِ وَالأَرْضِ يَا ذَا الْجَلالِ وَالإِكْرَامِ، يَا حَيُّ يَا قَيُّو",
